// Factory
function createNotifier(type) {
  if (type === 'email') return { send: (to, msg) => console.log(`Email to ${to}: ${msg}`) };
  if (type === 'sms') return { send: (to, msg) => console.log(`SMS to ${to}: ${msg}`) };
  throw new Error(`Unknown notifier: ${type}`);
}

