class Shape {
  area() { return 0; }
  describe() { return `Area: ${this.area()}`; }
}
class Circle extends Shape {
  constructor(r) { super(); this.r = r; }
  area() { return Math.PI * this.r ** 2; } // overriding
}

// "overloading" by checking the arguments
function greet(name, options = {}) {
  if (Array.isArray(name)) return name.map((n) => greet(n, options));
  return `${options.formal ? 'Dear' : 'Hi'} ${name}`;
}

class Node {
  constructor(value) { this.value = value; this.next = null; }
}
class LinkedList {
  constructor() { this.head = null; this.size = 0; }
  prepend(value) {            // O(1)
    const node = new Node(value);
    node.next = this.head;
    this.head = node;
    this.size++;
  }
  append(value) {             // O(n) without a tail pointer
    const node = new Node(value);
    if (!this.head) this.head = node;
    else {
      let cur = this.head;
      while (cur.next) cur = cur.next;
      cur.next = node;
    }
    this.size++;
  }
  toArray() {
    const out = [];
    for (let cur = this.head; cur; cur = cur.next) out.push(cur.value);
    return out;
  }
}

