// Queue with O(1) dequeue
class Queue {
  constructor() { this.items = []; this.head = 0; }
  enqueue(x) { this.items.push(x); }
  dequeue() {
    if (this.head >= this.items.length) return undefined;
    const x = this.items[this.head++];
    if (this.head > 1000 && this.head * 2 > this.items.length) {
      this.items = this.items.slice(this.head); // free memory now and then
      this.head = 0;
    }
    return x;
  }
  get size() { return this.items.length - this.head; }
}

const LINES = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
let board = Array(9).fill(null), player = 'X', winner = null;

function getWinner(b) {
  for (const [a, c, d] of LINES) if (b[a] && b[a] === b[c] && b[a] === b[d]) return b[a];
  return b.every(Boolean) ? 'draw' : null;
}

document.getElementById('board').addEventListener('click', (e) => {
  const i = Number(e.target.dataset.index);
  if (Number.isNaN(i) || board[i] || winner) return;
  board[i] = player;
  winner = getWinner(board);
  player = player === 'X' ? 'O' : 'X';
  render();
});

function render() {
  document.querySelectorAll('[data-index]').forEach((cell) => { cell.textContent = board[cell.dataset.index] || ''; });
  document.getElementById('status').textContent = winner === 'draw' ? 'Draw' : winner ? `${winner} wins` : `${player} to play`;
}

function insert(head, x) {
  const node = { value: x, next: null };
  if (!head) { node.next = node; return node; }
  let prev = head, next = head.next;
  do {
    const inGap = prev.value <= x && x <= next.value;
    const atTurn = prev.value > next.value && (x >= prev.value || x <= next.value);
    if (inGap || atTurn) break;
    prev = next;
    next = next.next;
  } while (prev !== head);
  prev.next = node;
  node.next = next;
  return head;
}
